"""Prepare real engine naming probes; no engine process is launched here."""
from pathlib import Path
import json
root=Path(__file__).resolve().parent.parent;home=root/'artifacts/ui-name-check';home.mkdir(exist_ok=True)
unity=root/'artifacts/runtime-ui-api-tests/UnitySource';core=Path(json.loads((root/'artifacts/core-engine-launch-tests/paths.json').read_text())['run'])
folder=unity/'Assets/EngineMigratorUINameProbe';(folder/'Editor').mkdir(parents=True,exist_ok=True)
(folder/'AuditUiName.cs').write_bytes((root/'tests/EngineMigrator.Checks/Fixtures/ui-name.cs.txt').read_bytes())
if(home/'restored.cs').exists():(folder/'RestoredAuditUiName.cs').write_text((home/'restored.cs').read_text().replace('AuditUiName','RestoredAuditUiName'))
editor='''using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class EMUiNameProbe{[Serializable]public class Row{public string source;public bool existing;public string stage;public string owner;public string copy;public bool panelOwner;public bool buttonOwner;}[Serializable]public class Result{public string status="CAPTURED";public List<Row> rows=new List<Row>();}
public static void Run(){try{var result=new Result();foreach(var name in new[]{"AuditUiName","RestoredAuditUiName"})foreach(bool existing in new[]{false,true}){var owner=new GameObject("Initial UI");if(existing){owner.AddComponent<Canvas>();owner.AddComponent<UnityEngine.UI.Button>();}var t=typeof(AuditUiName).Assembly.GetType(name);var actor=owner.AddComponent(t);t.GetField("Owner").SetValue(actor,owner);t.GetField("Existing").SetValue(actor,existing);foreach(var method in new[]{"InitUI","RenameCanvas","RenameButton","CloneOwner"}){t.GetMethod(method).Invoke(actor,null);var copy=(GameObject)t.GetField("Copy").GetValue(actor);var panel=(Canvas)t.GetField("Panel").GetValue(actor);var button=(UnityEngine.UI.Button)t.GetField("Action").GetValue(actor);result.rows.Add(new Row{source=name,existing=existing,stage=method,owner=owner.name,copy=copy?copy.name:"",panelOwner=panel.gameObject==owner,buttonOwner=button.gameObject==owner});}var finalCopy=(GameObject)t.GetField("Copy").GetValue(actor);if(finalCopy)UnityEngine.Object.DestroyImmediate(finalCopy);UnityEngine.Object.DestroyImmediate(owner);}File.WriteAllText(OUTPUT,JsonUtility.ToJson(result));EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}}
'''.replace('OUTPUT',json.dumps(str(home/'unity.json')))
(folder/'Editor/EMUiNameProbe.cs').write_text(editor)
runner=home/'runner';runner.mkdir(exist_ok=True);(runner/'Runner.csproj').write_bytes((root/'artifacts/ui-equality-check/destruction-runner/Runner.csproj').read_bytes())
code='''using EngineMigrator.Core;using System.Text.Json;
var home=HOME;var core=CORE;var unity=UNITY;string Hash(string p)=>Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(p)));
Dictionary<string,string> Files()=>Directory.GetFiles(Path.Combine(core,"Project/Source"),"*",SearchOption.AllDirectories).Concat(Directory.GetFiles(Path.Combine(core,"Project/Plugins/EMActorPort/Source"),"*",SearchOption.AllDirectories)).Where(p=>new[]{".h",".cpp",".cs"}.Contains(Path.GetExtension(p))).Concat(new[]{Path.Combine(core,"Project/Binaries/Win64/UnrealEditor-EMPortHost.dll"),Path.Combine(core,"Project/Plugins/EMActorPort/Binaries/Win64/UnrealEditor-EMActorPort.dll")}).ToDictionary(p=>p,Hash);
if(args.Length!=1)throw new ArgumentException("Explicit mode required");var mode=args[0];var descriptor=Path.Combine(core,"Project/RuntimeWorld.uproject");var manifest=Path.Combine(home,"build-hashes.json");
if(mode=="prepare"){File.WriteAllText(Path.Combine(core,"Project/Source/EMPortHost/EMPortHost.cpp"),File.ReadAllText("artifacts/ui-equality-check/core-host-before-ui-destruction.cpp.txt")+File.ReadAllText("artifacts/dynamic-ui-check/native-observer.cpp.txt")+File.ReadAllText("tools/ui-name-game-observer.cpp.txt"));var files=ActorScripts.FromUnity(File.ReadAllText("tests/EngineMigrator.Checks/Fixtures/ui-name.cs.txt"));File.WriteAllText(Path.Combine(home,"AuditUiName.h"),files.Single().Code);File.WriteAllText(Path.Combine(core,"Project/Plugins/EMActorPort/Source/EMActorPort/Public/AuditUiName.h"),files.Single().Code);File.WriteAllText(Path.Combine(home,"restored.cs"),ActorScripts.ToUnity(files).Single().Code);return;}
if(mode=="build"){using var timeout=new CancellationTokenSource(TimeSpan.FromMinutes(10));await ResourcePorting.RunEditor(EngineLaunchSafety.Dotnet,[EngineLaunchSafety.Ubt,"RuntimeWorldEditor","Win64","Development","-Project="+descriptor,"-NoHotReload","-NoPCH","-NoSharedPCH","-log="+Path.Combine(home,"build.log")],core,timeout.Token);File.WriteAllText(manifest,JsonSerializer.Serialize(Files()));return;}
if(mode=="unity"){var output=Path.Combine(home,"unity.json");if(File.Exists(output))throw new IOException("Fresh Unity capture required");var settings=Path.Combine(unity,"ProjectSettings/EditorSettings.asset");var before=File.ReadAllBytes(settings);try{using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(180));await ResourcePorting.RunEditor(EngineLaunchSafety.Unity,["-batchmode","-nographics","-projectPath",unity,"-executeMethod","EMUiNameProbe.Run","-logFile",Path.Combine(home,"unity.log")],Directory.GetParent(unity)!.FullName,timeout.Token);if(!File.Exists(output))throw new IOException("Unity capture missing");}finally{File.WriteAllBytes(settings,before);}return;}
var built=JsonSerializer.Deserialize<Dictionary<string,string>>(File.ReadAllText(manifest))!;var current=Files();if(built.Count!=current.Count||built.Any(p=>!current.TryGetValue(p.Key,out var hash)||hash!=p.Value))throw new IOException("Native source/binary build mismatch");
if(mode is "native-before" or "native"){var output=Path.Combine(home,mode+".json");if(File.Exists(output))throw new IOException("Fresh native capture required");var old=Environment.GetEnvironmentVariable("EM_UI_NAME_OUTPUT");Environment.SetEnvironmentVariable("EM_UI_NAME_OUTPUT",output);try{using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(180));await ResourcePorting.RunEditor(EngineLaunchSafety.Unreal,[descriptor,"/Engine/Maps/Entry","-game","-nullrhi","-RenderOffscreen","-nosound","-unattended","-nop4","-nosplash","-EMUINameProbe="+output,"-abslog="+Path.Combine(home,mode+".log")],core,timeout.Token);if(!File.Exists(output))throw new IOException("Native naming capture missing");}finally{Environment.SetEnvironmentVariable("EM_UI_NAME_OUTPUT",old);}return;}
if(mode is "dynamic" or "dynamic-static"){var output=Path.Combine(home,mode+".json");if(File.Exists(output))throw new IOException("Fresh dynamic regression required");using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(180));await ResourcePorting.RunEditor(EngineLaunchSafety.Unreal,[descriptor,"/Engine/Maps/Entry","-game","-nullrhi","-RenderOffscreen","-nosound","-nosplash","-unattended","-nop4","-UseFixedTimeStep","-FPS=50","-EMDynamicUIProbe="+output,"-EMDynamicUIExisting="+(mode.EndsWith("-static")?"1":"0"),"-abslog="+Path.Combine(home,mode+".log")],core,timeout.Token);if(!File.Exists(output))throw new IOException("Dynamic regression capture missing");return;}
throw new ArgumentException("Unknown mode");
'''
for key,value in [('HOME',str(home)),('CORE',str(core)),('UNITY',str(unity)),('SCRIPT',str(root/'tools/ui-name-native-probe.py'))]:code=code.replace(key,json.dumps(value))
(runner/'Program.cs').write_text(code)
print('UI_NAME_PROBES_PREPARED_NO_ENGINE_STARTED')
